/*
 * Tests for the library part registry (src/function_library_parts_internal.h,
 * generated by cmake/SxmlParts.cmake; D45, D101).
 *
 * Golden file: tests/memory_test.c (fixture, allocation-failure loops),
 * with the library fixture of tests/function_library_test.c. The registry
 * must list every Phase 1 part, sorted and once; each language's list must
 * be the parts that serve it, in the same order; a declared language set
 * must agree with what CMake read; and a library made from the XPath list,
 * as the processor makes it, must hold no name and arity twice.
 */
#include "function_library_parts_internal.h"
#include "sxml/name.h"
#include "sxml/types.h"
#include "sxml/xdm.h"
#include "test_runner.h"

#include <stdalign.h>
#include <string.h>

static sxml_byte_view text_view(const char *text) {
    return (sxml_byte_view){.bytes = (const uint8_t *)text, .byte_count = strlen(text)};
}

/* Negative, zero or positive as first sorts before, with or after second,
   byte by byte. */
static int compare_names(sxml_byte_view first, sxml_byte_view second) {
    const size_t common_count =
        first.byte_count < second.byte_count ? first.byte_count : second.byte_count;
    const int common_order = memcmp(first.bytes, second.bytes, common_count);
    if (common_order != 0) {
        return common_order;
    }
    if (first.byte_count == second.byte_count) {
        return 0;
    }
    return first.byte_count < second.byte_count ? -1 : 1;
}

static const sxml_function_library_part *find_part(sxml_byte_view part_name) {
    const sxml_function_library_part_view registered =
        sxml_function_library_registered_parts();
    for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
        if (sxml_byte_view_equals(registered.parts[part_index].part_name, part_name)) {
            return &registered.parts[part_index];
        }
    }
    return NULL;
}

/* ---------------------------------------------------------- Registry */

static void test_registry_lists_every_part_once(sxml_test_state *state) {
    static const char *const phase_1_parts[] = {
        "array", "context", "error", "higher_order", "json", "map", "math",
        "node", "numeric", "qname", "sequence", "string", "uri",
    };
    for (size_t name_index = 0; name_index < SXML_TEST_COUNT(phase_1_parts);
         name_index += 1) {
        const sxml_function_library_part *part = find_part(text_view(phase_1_parts[name_index]));
        SXML_TEST_EXPECT(state, part != NULL);
        if (part != NULL) {
            SXML_TEST_EXPECT(state, part->native_functions != NULL &&
                                        part->native_functions->native_function_count > 0);
        }
    }
    /* Files of the prefix that define no part are not parts. */
    SXML_TEST_EXPECT(state, find_part(text_view("case")) == NULL);
    SXML_TEST_EXPECT(state, find_part(text_view("deep_equal")) == NULL);
    const sxml_function_library_part_view registered =
        sxml_function_library_registered_parts();
    SXML_TEST_EXPECT(state, registered.part_count >= SXML_TEST_COUNT(phase_1_parts));
    for (size_t part_index = 1; part_index < registered.part_count; part_index += 1) {
        SXML_TEST_EXPECT(state, compare_names(registered.parts[part_index - 1].part_name,
                                              registered.parts[part_index].part_name) < 0);
    }
}

static void test_declared_languages_agree(sxml_test_state *state) {
    const sxml_function_library_part_view registered =
        sxml_function_library_registered_parts();
    for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
        const sxml_function_library_part *part = &registered.parts[part_index];
        SXML_TEST_EXPECT(state, part->languages != 0 &&
                                    (part->languages & ~SXML_LANGUAGE_SET_ALL) == 0);
        if (part->declared_languages == NULL) {
            SXML_TEST_EXPECT(state, part->languages == SXML_LANGUAGE_SET_ALL);
        } else {
            SXML_TEST_EXPECT(state, *part->declared_languages == part->languages);
        }
    }
}

static void test_language_lists_follow_the_registry(sxml_test_state *state) {
    static const sxml_language languages[] = {SXML_LANGUAGE_XPATH, SXML_LANGUAGE_XQUERY,
                                              SXML_LANGUAGE_XSLT};
    const sxml_function_library_part_view registered =
        sxml_function_library_registered_parts();
    for (size_t language_index = 0; language_index < SXML_TEST_COUNT(languages);
         language_index += 1) {
        const sxml_language language = languages[language_index];
        const sxml_native_function_view_list list =
            sxml_function_library_parts_for_language(language);
        size_t list_index = 0;
        for (size_t part_index = 0; part_index < registered.part_count; part_index += 1) {
            const sxml_function_library_part *part = &registered.parts[part_index];
            if ((part->languages & (sxml_language_set)language) == 0) {
                continue;
            }
            SXML_TEST_EXPECT(state, list_index < list.native_function_view_count &&
                                        list.native_function_views[list_index] ==
                                            part->native_functions);
            list_index += 1;
        }
        SXML_TEST_EXPECT(state, list_index == list.native_function_view_count);
    }
}

/* ------------------------------------------------------------ Library */

typedef struct fixture {
    sxml_counting_allocator *counting_allocator;
    alignas(16) uint8_t counting_storage[256];
    sxml_name_pool *name_pool;
    sxml_type_registry *registry;
    sxml_item_heap *item_heap;
    sxml_function_library *library;
} fixture;

static sxml_allocator fixture_allocator(const fixture *test_fixture) {
    return sxml_counting_allocator_as_allocator(test_fixture->counting_allocator);
}

/* Makes the fixture and a library of the XPath parts, as the processor
   does (src/processor.c). */
static sxml_status fixture_create(uint64_t failing_allocation_number,
                                  fixture *test_fixture) {
    *test_fixture = (fixture){.counting_allocator = NULL};
    sxml_status status = sxml_counting_allocator_initialize(
        (sxml_memory_view){.bytes = test_fixture->counting_storage,
                           .byte_count = sizeof(test_fixture->counting_storage)},
        &(sxml_counting_allocator_configuration){
            .backing_allocator = sxml_default_allocator(),
            .failing_allocation_number = failing_allocation_number},
        &test_fixture->counting_allocator);
    if (status == SXML_STATUS_OK) {
        status = sxml_name_pool_create(
            sxml_default_allocator(),
            &(sxml_name_pool_configuration){.allocator = sxml_default_allocator(),
                                            .maximum_byte_count = 0},
            &test_fixture->name_pool);
    }
    if (status == SXML_STATUS_OK) {
        status = sxml_type_registry_create(
            sxml_default_allocator(),
            &(sxml_type_registry_configuration){.allocator = sxml_default_allocator(),
                                                .name_pool = test_fixture->name_pool,
                                                .maximum_registered_type_count = 0},
            &test_fixture->registry);
    }
    if (status == SXML_STATUS_OK) {
        status = sxml_item_heap_create(
            fixture_allocator(test_fixture),
            &(sxml_item_heap_configuration){.allocator = fixture_allocator(test_fixture),
                                            .name_pool = test_fixture->name_pool,
                                            .type_registry = test_fixture->registry,
                                            .maximum_byte_count = 0},
            &test_fixture->item_heap);
    }
    if (status == SXML_STATUS_OK) {
        status = sxml_function_library_create(
            fixture_allocator(test_fixture),
            &(sxml_function_library_configuration){
                .allocator = fixture_allocator(test_fixture),
                .item_heap = test_fixture->item_heap,
                .parts = sxml_function_library_parts_for_language(SXML_LANGUAGE_XPATH)},
            &test_fixture->library);
    }
    return status;
}

/* Destroys the fixture; true when every block was released. */
static bool fixture_destroy(fixture *test_fixture) {
    sxml_function_library_destroy(test_fixture->library);
    sxml_item_heap_destroy(test_fixture->item_heap);
    sxml_type_registry_destroy(test_fixture->registry);
    sxml_name_pool_destroy(test_fixture->name_pool);
    bool released = true;
    if (test_fixture->counting_allocator != NULL) {
        released = sxml_counting_allocator_read_counts(test_fixture->counting_allocator)
                       .live_allocation_count == 0;
        sxml_counting_allocator_finalize(test_fixture->counting_allocator);
    }
    *test_fixture = (fixture){.counting_allocator = NULL};
    return released;
}

static void test_xpath_parts_make_one_library(sxml_test_state *state) {
    fixture test_fixture;
    SXML_TEST_EXPECT(state, fixture_create(0, &test_fixture) == SXML_STATUS_OK);
    SXML_TEST_EXPECT(state, fixture_destroy(&test_fixture));
}

static void test_library_survives_every_allocation_failure(sxml_test_state *state) {
    bool succeeded = false;
    for (uint64_t failing_allocation_number = 1; !succeeded && failing_allocation_number < 10000;
         failing_allocation_number += 1) {
        fixture test_fixture;
        const sxml_status status = fixture_create(failing_allocation_number, &test_fixture);
        succeeded = status == SXML_STATUS_OK;
        SXML_TEST_EXPECT(state, succeeded || status == SXML_STATUS_OUT_OF_MEMORY);
        SXML_TEST_EXPECT(state, fixture_destroy(&test_fixture));
    }
    SXML_TEST_EXPECT(state, succeeded);
}

static const sxml_test_case function_library_parts_test_cases[] = {
    {.name = "registry_lists_every_part_once", .function = test_registry_lists_every_part_once},
    {.name = "declared_languages_agree", .function = test_declared_languages_agree},
    {.name = "language_lists_follow_the_registry",
     .function = test_language_lists_follow_the_registry},
    {.name = "xpath_parts_make_one_library", .function = test_xpath_parts_make_one_library},
    {.name = "library_survives_every_allocation_failure",
     .function = test_library_survives_every_allocation_failure},
};

int main(int argument_count, char **arguments) {
    return sxml_test_run_suite(
        &(sxml_test_suite){
            .name = "function_library_parts",
            .cases = function_library_parts_test_cases,
            .case_count = SXML_TEST_COUNT(function_library_parts_test_cases),
        },
        (sxml_test_command_line){
            .argument_count = argument_count,
            .arguments = arguments,
        });
}
